import { useEffect } from 'react'
import { connect } from 'react-redux'
import { Form, Modal, Input, notification, Switch, Select } from 'antd'
import ServiceCenterActions from '../../redux/serviceCenter/actions'
import ErrorAction from '../../../redux/error/actions'
import LoadingActions from '../../../redux/loading/actions'

const { createServiceCenter, updateServiceCenter, resetServiceCenterRedux } = ServiceCenterActions
const { resetErrorRedux } = ErrorAction
const { resetLoadingRedux } = LoadingActions

const countryOptions = [
  {
    label: 'Indonesia',
    value: 'Indonesia'
  },
  {
    label: 'Vietnam',
    value: 'Vietnam'
  },
  {
    label: 'Thaliland',
    value: 'Thailand'
  }
]

function AddServiceCenterModal ({
  form,
  data = {},
  isOpen,
  resetErrorRedux,
  onClosePopupForm,
  resetLoadingRedux,
  updateServiceCenter,
  createServiceCenter,
  resetServiceCenterRedux,
  createServiceCenterError,
  updateServiceCenterError,
  updateServiceCenterLoading,
  createServiceCenterMessage,
  createServiceCenterLoading,
  updateServiceCenterDataMessage
}) {
  const { getFieldDecorator } = form

  useEffect(() => {
    if (createServiceCenterLoading === false) {
      if (createServiceCenterError) {
        notification.error({
          message: createServiceCenterMessage
        })
        resetServiceCenterRedux(['createServiceCenterMessage'])
      } else {
        createServiceCenterMessage && notification.success({
          message: createServiceCenterMessage
        })
        form.resetFields()
        onClosePopupForm()
      }
      resetLoadingRedux(['CREATE_SERVICE_CENTER'])
      resetErrorRedux(['CREATE_SERVICE_CENTER'])
    }
  }, [
    form,
    resetErrorRedux,
    onClosePopupForm,
    resetLoadingRedux,
    resetServiceCenterRedux,
    createServiceCenterError,
    createServiceCenterMessage,
    createServiceCenterLoading
  ])

  useEffect(() => {
    if (updateServiceCenterLoading === false) {
      if (updateServiceCenterError) {
        notification.error({
          message: updateServiceCenterDataMessage || 'Error'
        })
        resetServiceCenterRedux(['updateServiceCenterDataMessage'])
        resetErrorRedux(['UPDATE_SERVICE_CENTER'])
      } else {
        updateServiceCenterDataMessage && notification.success({
          message: updateServiceCenterDataMessage
        })
        resetServiceCenterRedux(['updateServiceCenterDataMessage'])
        onClosePopupForm()
      }
      resetLoadingRedux(['UPDATE_SERVICE_CENTER'])
    }
  }, [
    resetErrorRedux,
    onClosePopupForm,
    resetLoadingRedux,
    resetServiceCenterRedux,
    updateServiceCenterError,
    updateServiceCenterLoading,
    updateServiceCenterDataMessage
  ])

  const submitServiceCenter = () => {
    form.validateFields((err, values) => {
      if (err) return
      if (data.name) {
        updateServiceCenter({
          ...values,
          name: encodeURI(values.name),
          code: data.code
        })
        return
      }
      createServiceCenter({
        ...values,
        name: encodeURI(values.name)
      })
    })
  }

  return (
    <Modal
      visible={isOpen}
      okText='Submit'
      onOk={submitServiceCenter}
      onCancel={onClosePopupForm}
      handleCancel={onClosePopupForm}
      okButtonProps={{ loading: createServiceCenterLoading || updateServiceCenterLoading }}
      closable
    >
      <Form form={form} name='add-service-center'>
        <Form.Item label='Service Center Name'>
          {
            getFieldDecorator('name', {
              rules: [
                { required: true, message: 'Service center name is required' }
              ],
              initialValue: data.name
            })(
              <Input placeholder='Enter service center name' disabled={!!data.name} />
            )
          }
        </Form.Item>

        <Form.Item label='Email Adress'>
          {getFieldDecorator('contact_email', {
            rules: [
              { required: true, message: 'Email Adress is required' },
              {
                type: 'email',
                message: 'The input is not valid E-mail!'
              }
            ],
            initialValue: data.contact_email
          })(
            <Input placeholder='Enter email adress' />
          )}
        </Form.Item>

        <Form.Item label='Country'>
          {getFieldDecorator('country', {
            rules: [
              { required: true, message: 'Country is required' }
            ],
            initialValue: data.country
          })(
            <Select
              placeholder='Enter country'
              disabled={!!data.country}
            >
              {countryOptions.map(({ label, value }) => (
                <Select.Option value={value} key={value}>
                  {label}
                </Select.Option>
              ))}
            </Select>
          )}
        </Form.Item>

        {!!data && data.is_active !== undefined
          ? (
            <Form.Item label='Active'>
              {getFieldDecorator('is_active',
                {
                  valuePropName: 'checked',
                  initialValue: !!data.is_active
                })(<Switch />)}
            </Form.Item>
            )
          : null}

      </Form>
    </Modal>
  )
}

const FormWrapper = Form.create()(AddServiceCenterModal)

export default connect((state) => ({

  createServiceCenterLoading: state.Loading.CREATE_SERVICE_CENTER,
  createServiceCenterError: state.Error.CREATE_SERVICE_CENTER,

  createServiceCenterMessage: state.ServiceCenter.createServiceCenterMessage,
  updateServiceCenterDataMessage: state.ServiceCenter.updateServiceCenterDataMessage,

  updateServiceCenterLoading: state.Loading.UPDATE_SERVICE_CENTER,
  updateServiceCenterError: state.Error.UPDATE_SERVICE_CENTER
}), {
  resetLoadingRedux,
  resetServiceCenterRedux,
  createServiceCenter,
  resetErrorRedux,
  updateServiceCenter
})(FormWrapper)
