import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { useHistory, useLocation } from 'react-router-dom'
import { Button, Form, notification, Modal } from 'antd'
import _ from 'lodash'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import FileUploadOnGcsV2 from '../../../components/FileUploadOnGcsV2'
import PermissionChecker from '../../../components/permissionChecker'
import PermissionCheckerV2 from '../../../components/permissionCheckerV2'
import fileUrls from '../../../request/urls/file'

import serviceActions from '../../redux/serviceCenter/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'

import {
  FlexConatiner,
  DownloadButton,
  ButtonContainer
} from './serviceCenterDetailStyle'

const { confirm } = Modal

const { uploadBranchBulkDetails, resetServiceCenterRedux } = serviceActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const downloadSheetLink = 'https://storage.googleapis.com/pp-tmp-jkt/sample_service_center_file_revised_template%20.csv'
function BulkUploadBranchDetails ({
  form,
  profileData,
  resetErrorRedux,
  serviceCenterCode,
  resetLoadingRedux,
  bulkUploadBranchMessage,
  uploadBranchBulkDetails,
  resetServiceCenterRedux,
  bulkUploadBranchDataError,
  bulkUploadBranchDataLoading
}) {
  const history = useHistory()
  const location = useLocation()

  const { getFieldDecorator } = form
  const permissions = _.get(profileData, 'permissions', [])

  const [isFileUploaded, setIsFileUploaded] = useState(false)

  useEffect(() => {
    if (bulkUploadBranchDataLoading === false) {
      if (bulkUploadBranchDataError === true) {
        notification.error({
          message: 'Error',
          description: bulkUploadBranchMessage,
          style: {
            wordBreak: 'break-word'
          }
        })
      } else {
        notification.success({
          message: bulkUploadBranchMessage || 'Error'
        })
        form.resetFields()
        setIsFileUploaded(false)
        history.push({ location: location.pathname, search: QuerySearchBuilder({ page: 1 }) })
      }
      resetServiceCenterRedux(['bulkUploadBranchData', 'bulkUploadBranchMessage'])
      resetErrorRedux(['UPLOAD_BULK_BRANCH_DETAIL'])
      resetLoadingRedux(['UPLOAD_BULK_BRANCH_DETAIL'])
    }
  }, [
    form,
    history,
    resetErrorRedux,
    location.pathname,
    resetLoadingRedux,
    bulkUploadBranchMessage,
    resetServiceCenterRedux,
    bulkUploadBranchDataError,
    bulkUploadBranchDataLoading
  ])

  const uploadBranchDetailsclickHandler = () => {
    form.validateFields((err, values) => {
      if (err) return

      function showConfirm () {
        confirm({
          title: 'You are going to upload new data for service branch list, Are you sure?',
          onOk () {
            let fileUrl = values['bulk-branch-file'][0]?.url || ''
            const bucketName = fileUrl.split('https://')[1].split('/')[0]

            fileUrl = fileUrl.split('s3.ap-southeast-3.amazonaws.com')[1]
            fileUrl = `/${bucketName.split('.')[0]}${fileUrl}`
            fileUrl = fileUrl.split('s3')[1]

            const payload = {
              uploaded_file: `s3:/${fileUrl}`,
              service_center_code: serviceCenterCode
            }
            uploadBranchBulkDetails(payload)
          },
          onCancel () {
          }
        })
      }
      showConfirm()
    })
  }

  const redirectToAddNewBrach = () => {
    history.push(`/service-center/${serviceCenterCode}/branch/create-branch`)
  }
  const onFileUploadedSuccess = () => {
    setIsFileUploaded(true)
  }

  return (
    <FlexConatiner>
      <PermissionChecker permissionSetter='ops.create_service_center' permissionGetter={permissions}>
        <Form layout='inline'>
          <Form.Item help='only .csv file allowed'>
            <FileUploadOnGcsV2
              signedUrlEndPoint={fileUrls.generateSignedURL}
              getFieldDecorator={getFieldDecorator}
              name='bulk-branch-file'
              identifier='claims'
              minSize={0.00}
              form={form}
              maxFileAllowed={1}
              buttonText='Choose File'
              buttonClassName='fluid-width'
              icon='cloud-upload'
              required
              maxSize={10}
              onPreview={false}
              accept='.csv'
              formItemProps={{ label: 'Bulk Update Branch' }}
              fileNameLength={25}
              onFileUploadedSuccess={onFileUploadedSuccess}
            />
          </Form.Item>
          <Button
            type='primary'
            onClick={uploadBranchDetailsclickHandler}
            loading={bulkUploadBranchDataLoading}
            disabled={!isFileUploaded}
          >
            Upload
          </Button>
        </Form>
      </PermissionChecker>

      <PermissionCheckerV2
        permissions={permissions}
        requiredPermission='ops.update_service_center'
      >
        <ButtonContainer>
          <Button onClick={redirectToAddNewBrach}>
            Create new branch
          </Button>

          <DownloadButton>
            <a download href={downloadSheetLink}>
              Download Example Sheet
            </a>
          </DownloadButton>
        </ButtonContainer>
      </PermissionCheckerV2>
    </FlexConatiner>
  )
}

const FormWrapper = Form.create()(BulkUploadBranchDetails)

export default connect((state) => ({
  bulkUploadBranchData: state.ServiceCenter.bulkUploadBranchData,
  bulkUploadBranchMessage: state.ServiceCenter.bulkUploadBranchMessage,

  bulkUploadBranchDataError: state.Error.UPLOAD_BULK_BRANCH_DETAIL,
  bulkUploadBranchDataLoading: state.Loading.UPLOAD_BULK_BRANCH_DETAIL,
  profileData: state.Auth.profile
}), {
  resetErrorRedux,
  resetLoadingRedux,
  uploadBranchBulkDetails,
  resetServiceCenterRedux
})(FormWrapper)
