import { Button, Form, Input, Select, Row, notification } from 'antd'
import FormItem from 'antd/lib/form/FormItem'
import { connect } from 'react-redux'

import ServiceCenterActions from '../../redux/serviceCenter/actions'
import ErrorAction from '../../../redux/error/actions'
import LoadingActions from '../../../redux/loading/actions'
import { useEffect } from 'react'

const {
  addServicecenterUser,
  resetServiceCenterRedux
} = ServiceCenterActions

const { resetErrorRedux } = ErrorAction
const { resetLoadingRedux } = LoadingActions

const Option = Select.Option
function AddServiceCenterUser (props) {
  const {
    form,
    visible,
    closeModal,
    editUserData,
    resetErrorRedux,
    resetLoadingRedux,
    serviceCenterCode,
    addServicecenterUser,
    serviceCenterGroupList,
    resetServiceCenterRedux,
    createServiceCenterUserError,
    serviceCenterGroupListLoading,
    createServiceCenterUserLoading,
    addServiceCenterUserDataMessage
  } = props
  const { getFieldDecorator } = form

  useEffect(() => {
    if (!visible) {
      form.resetFields()
    }
  }, [
    visible
  ])

  useEffect(() => {
    if (createServiceCenterUserLoading === false) {
      notification[createServiceCenterUserError ? 'error' : 'success']({
        message: addServiceCenterUserDataMessage || 'error'
      })
      resetErrorRedux(['ADD_SERVICE_CENTER_USER'])
      resetLoadingRedux(['ADD_SERVICE_CENTER_USER'])
      resetServiceCenterRedux(['addServiceCenterUserDataMessage'])
      if (createServiceCenterUserError === false) {
        closeModal()
      }
    }
  }, [
    closeModal,
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    createServiceCenterUserError,
    createServiceCenterUserLoading,
    addServiceCenterUserDataMessage
  ])

  const submitServiceCenterUser = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (err) return
      const isEdit = !!(Object.keys(editUserData).length)
      addServicecenterUser({
        ...values,
        user_type: 'service_center',
        code: serviceCenterCode,
        ...(isEdit ? { user_id: editUserData.id } : {}),
        isEdit
      })
    })
  }
  return (
    <>
      <Form onSubmit={submitServiceCenterUser}>
        <FormItem label='Name'>
          {getFieldDecorator('name', {
            rules: [
              { required: true, message: 'Name can not be empty' }
            ],
            initialValue: editUserData.name || ''
          })(
            <Input />
          )}
        </FormItem>

        <FormItem label='Email address'>
          {getFieldDecorator('email', {
            rules: [
              {
                required: true,
                pattern: /[a-zA-Z0-9+_.-]+@[a-zA-Z0-9.-]+$/,
                message: 'invalid mail '
              }
            ],
            initialValue: editUserData.email || ''
          }
          )(
            <Input disabled={!!editUserData.email || ''} />
          )}
        </FormItem>

        <FormItem
          label='Groups'
          help={serviceCenterGroupListLoading ? '' : Array.isArray(serviceCenterGroupList) && serviceCenterGroupList.length > 0 ? '' : 'Groups api is not working'}
        >
          {getFieldDecorator('groups', {
            rules: [
              { required: true, message: 'groups can not be empty' }
            ],
            initialValue: Array.isArray(editUserData.groups) ? editUserData.groups.map(({ name }) => name) : []
          })(
            <Select
              showSearch
              mode='multiple'
              loading={serviceCenterGroupListLoading}
            >
              {Array.isArray(serviceCenterGroupList)
                ? serviceCenterGroupList.map((group) => (
                  <Option key={group} value={group}>
                    {group}
                  </Option>
                  ))
                : null}
            </Select>
          )}
        </FormItem>

        <FormItem label='Is internal user'>
          {getFieldDecorator('is_internal_user', {
            rules: [
              { required: true, message: 'internal user can not be empty' }
            ],
            initialValue: editUserData.is_internal_user ?? undefined
          })(
            <Select disabled={!!(Object.keys(editUserData).length)}>
              <Option value>Yes</Option>
              <Option value={false}>No</Option>
            </Select>
          )}
        </FormItem>
        <Row type='flex' justify='end'>
          <FormItem>
            <Button
              loading={createServiceCenterUserLoading}
              type='primary'
              htmlType='submit'
            >
              Submit
            </Button>
          </FormItem>
        </Row>
      </Form>
    </>
  )
}

export default (Form.create({
  validateTrigger: ''
})(connect((state) => ({
  addServiceCenterUserDataMessage: state.ServiceCenter.addServiceCenterUserDataMessage,
  createServiceCenterUserError: state.Error.ADD_SERVICE_CENTER_USER,
  createServiceCenterUserLoading: state.Loading.ADD_SERVICE_CENTER_USER,

  serviceCenterGroupList: state.ServiceCenter.serviceCenterGroupList,
  serviceCenterGroupListLoading: state.Loading.GET_SERVICE_CENTER_USER_GROUP_LIST
}), {
  resetServiceCenterRedux,
  resetLoadingRedux,
  resetErrorRedux,
  addServicecenterUser
})(AddServiceCenterUser)))
