import { forwardRef, useEffect, useState } from 'react'
import { Checkbox, Button } from 'antd'
import { FilterBrandStyle } from './serviceCenterDetailStyle'

const FilterBrand = forwardRef(({ brandList = [], onChange, selectedBrand }, ref) => {
  const [selected, setSelected] = useState([])

  useEffect(() => {
    setSelected(selectedBrand ? selectedBrand.split(',') : [])
  }, [selectedBrand])

  const onChangeHandler = (e, code) => {
    e.preventDefault()
    e.stopPropagation()
    let newSelected = [...selected]
    if (e.target.checked) {
      newSelected.push(code)
    } else {
      newSelected = newSelected.filter((el) => code !== el)
    }
    setSelected(newSelected)
  }

  return (
    <FilterBrandStyle ref={ref}>
      {
        brandList.map(({ code, name }) => {
          return (
            <Checkbox
              checked={selected.includes(code)}
              onChange={(e) => onChangeHandler(e, code)}
              key={code}
            >
              {name}
            </Checkbox>
          )
        })
    }
      <div className='bottom'>
        <Button
          type='primary'
          onClick={() => onChange(selected)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Ok
        </Button>
        <Button onClick={() => onChange()}>
          Reset
        </Button>
      </div>

    </FilterBrandStyle>
  )
})

export default FilterBrand
