import { Col, Row, Spin, Card } from 'antd'
import { ErrorText } from '../serviceCenterDetailStyle'

function DisplayServiceCenterConfigValues ({
  configData,
  existingServiceCenterMessage,
  getExistingServiceCenterConfigError,
  getExistingServiceCenterConfigLoading
}) {
  const displayConfig = ({ value, config_type: configType }) => {
    const { description } = configType
    let configValue = value
    if (value === '1') {
      configValue = 'True'
    } else if (value === '0') {
      configValue = 'False'
    }
    return (
      <Col key={description} span={8} className='config-column'>
        <Row className='config-header'>{description}</Row>
        {configValue}
      </Col>
    )
  }

  const renderContent = () => {
    if (getExistingServiceCenterConfigLoading) return null
    if (getExistingServiceCenterConfigError) {
      return (
        <ErrorText>
          {existingServiceCenterMessage || 'There was some error while receiving existing config '}
        </ErrorText>
      )
    }
    if (Array.isArray(configData) && configData.length > 0) {
      return (
        configData.map((config) => displayConfig(config))
      )
    }

    return (
      <Card>
        There is no active service center configs
      </Card>
    )
  }

  return (
    <Spin spinning={!!getExistingServiceCenterConfigLoading}>
      {renderContent()}
    </Spin>
  )
}

export default DisplayServiceCenterConfigValues
