import { useState, useEffect } from 'react'
import { get } from 'lodash'
import { connect } from 'react-redux'
import { Button, Col, Modal, Row, notification } from 'antd'

import DisplayServiceCenterConfigValues from './displayServiceCenterConfigValues'

import {
  ServiceCenterConfigContainer
} from './servicecenterConfig.style'

import ServiceCenterActions from '../../../redux/serviceCenter/actions'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'
import AddEditServiceCenterConfig from './AddEditServiceCenterConfigValues'
import { useParams } from 'react-router'
import PermissionCheckerV2 from '../../../../components/permissionCheckerV2'

const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const {
  resetServiceCenterRedux,
  getExistingServiceCenterConfig,
  submitServiceCenterConfig,
  getServiceCenterDefaultConfig
} = ServiceCenterActions
function ServiceCenterConfig ({
  defaultConfigList,
  resetServiceCenterRedux,
  existingServiceCenterMessage,
  getExistingServiceCenterConfigError,
  getExistingServiceCenterConfigLoading,
  getServiceCenterDefaultConfig,
  existingServiceCenterConfig,
  getExistingServiceCenterConfig,
  submitServiceCenterConfig,
  submitServiceCenterMessage,
  addEditServiceCenterConfigError,
  addEditServiceCenterConfigLoading
}) {
  const params = useParams()

  const servicecenterCode = get(params, 'id', '')

  const [showAddConfigModal, setAddConfigModal] = useState(false)

  useEffect(() => {
    getExistingServiceCenterConfig({
      serviceuser_code: servicecenterCode
    })
    getServiceCenterDefaultConfig()
  }, [
    servicecenterCode
  ])

  useEffect(() => {
    if (addEditServiceCenterConfigLoading === false && submitServiceCenterMessage) {
      notification[addEditServiceCenterConfigError ? 'error' : 'success']({
        message: submitServiceCenterMessage
      })
      if (addEditServiceCenterConfigError === false) {
        setAddConfigModal(false)
      }
      resetLoadingRedux(['SUBMIT_SERVICE_CENTER_CONFIG'])
      resetErrorRedux(['SUBMIT_SERVICE_CENTER_CONFIG'])
      resetServiceCenterRedux(['submitServiceCenterMessage'])
    }
  }, [
    submitServiceCenterMessage,
    addEditServiceCenterConfigError,
    addEditServiceCenterConfigLoading
  ])

  const submitServiceCenterConfigDetails = (payload) => {
    submitServiceCenterConfig(payload)
  }
  const handleCancel = () => {
    setAddConfigModal(false)
  }

  return (
    <ServiceCenterConfigContainer>
      <Modal
        footer={null}
        visible={showAddConfigModal}
        onCancel={() => setAddConfigModal(false)}
      >
        <AddEditServiceCenterConfig
          existingServiceCenterConfig={existingServiceCenterConfig}
          handleCancel={handleCancel}
          defaultConfigList={defaultConfigList}
          submitServiceCenterConfig={submitServiceCenterConfigDetails}
          addEditServiceCenterConfigLoading={addEditServiceCenterConfigLoading}
        />
      </Modal>
      <Row type='flex' justify='space-between'>
        <Col className='header'>Service Center Configs</Col>
        <PermissionCheckerV2 requiredPermission='ops.update_service_center'>
          <Col>
            {
            getExistingServiceCenterConfigError
              ? (
                <Button
                  type='primary'
                  icon='form'
                  onClick={() => setAddConfigModal(true)}
                >
                  {
                    Array.isArray(existingServiceCenterConfig) && existingServiceCenterConfig.length > 0
                      ? 'Update Config'
                      : 'Add Config'
                  }
                </Button>
                )
              : (
                <Button
                  type='primary'
                  icon='form'
                  onClick={() => setAddConfigModal(true)}
                >
                  {
                    Array.isArray(existingServiceCenterConfig) && existingServiceCenterConfig.length > 0
                      ? 'Update Config'
                      : 'Add Config'
                  }
                </Button>
                )
          }
          </Col>
        </PermissionCheckerV2>

      </Row>
      <DisplayServiceCenterConfigValues
        configData={existingServiceCenterConfig}
        existingServiceCenterMessage={existingServiceCenterMessage}
        getExistingServiceCenterConfigError={getExistingServiceCenterConfigError}
        getExistingServiceCenterConfigLoading={getExistingServiceCenterConfigLoading}
      />
    </ServiceCenterConfigContainer>
  )
}

export default connect((state) => ({
  defaultConfigList: state.ServiceCenter.defaultConfigList,
  getExistingServiceCenterConfigLoading: state.Loading.GET_SERVICE_CENTER_EXISTING_CONFIG,
  submitServiceCenterMessage: state.ServiceCenter.submitServiceCenterMessage,
  existingServiceCenterConfig: state.ServiceCenter.existingServiceCenterConfig,
  existingServiceCenterMessage: state.ServiceCenter.existingServiceCenterMessage,
  addEditServiceCenterConfigError: state.Error.SUBMIT_SERVICE_CENTER_CONFIG,
  addEditServiceCenterConfigLoading: state.Loading.SUBMIT_SERVICE_CENTER_CONFIG,
  getExistingServiceCenterConfigError: state.Error.GET_SERVICE_CENTER_EXISTING_CONFIG
}), {
  resetServiceCenterRedux,
  getExistingServiceCenterConfig,
  submitServiceCenterConfig,
  getServiceCenterDefaultConfig
})(ServiceCenterConfig)
