import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Row, Button, Card, Spin, Icon, Col, Upload, notification } from 'antd'
import ErrorBoundary from '../../../components/ErrorBoundary'
import ServiceCenterActions from '../../redux/serviceCenter/actions'
import LayoutContent from '../../../components/utility/layoutContent'

import BulkUploadBranchDetails from './bulkUploadBranch'
import AddServiceCenterDetail from './addServiceCenter'
import ServicecenterConfig from './ServiceCenterConfig'
import BranchList from './branchList'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'

import {
  ButtonWrapper,
  RightSideButton,
  BankButtonWrapper
} from './serviceCenterDetailStyle'
import PermissionChecker from '../../../components/permissionChecker'
import ServiceCenterUser from './serviceCenterUser'
import { useHistory, useParams } from 'react-router'

const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const { getServiceCenterDetails } = ServiceCenterActions

const servicecenterDetail = [
  {
    dataIndex: 'name',
    title: 'Service Center Name',
    render: (value) => {
      return decodeURI(value)
    }
  },
  {
    dataIndex: 'contact_email',
    title: 'Email Adress'
  },
  {
    dataIndex: 'code',
    title: 'Code'
  },
  {
    dataIndex: 'country',
    title: 'Country'
  },
  {
    dataIndex: 'is_active',
    title: 'Active',
    render: (data) => data !== undefined ? data ? 'Active' : 'Inactive' : ''
  }
]

const antIcon = <Icon type='loading' style={{ fontSize: 24 }} spin />
function ServiceCenterDetails (props) {
  const params = useParams()
  const history = useHistory()
  const { id } = params

  const [updateModalOpen, setUpdateModalOpen] = useState(false)

  const {
    permissions,
    resetErrorRedux,
    resetLoadingRedux,
    getServiceCenterDetails,
    serviceCenterDetailData,
    getServiceCenterDetailsError,
    getServiceCenterDetailsLoading
  } = props

  useEffect(() => {
    if (getServiceCenterDetailsError) {
      notification.error({
        message: 'Service center details not found'
      })
      history.push('/service-center/lists')
      resetErrorRedux(['GET_SERVICE_CENTER_DETAIL'])
      resetLoadingRedux(['GET_SERVICE_CENTER_DETAIL'])
    }
  }, [
    props.history,
    resetErrorRedux,
    resetLoadingRedux,
    getServiceCenterDetailsError
  ])

  useEffect(() => {
    getServiceCenterDetails({ id: id })
  }, [getServiceCenterDetails, id])

  const onClosePopupForm = () => {
    setUpdateModalOpen(false)
  }

  return (
    <ErrorBoundary>
      <LayoutContent className='referral-table' style={{ color: '#788195' }}>

        <AddServiceCenterDetail
          isOpen={updateModalOpen}
          onClosePopupForm={onClosePopupForm}
          data={serviceCenterDetailData}
        />

        <ButtonWrapper>
          <Button
            type='primary'
            icon='arrow-left'
            className='back-button'
            onClick={() => props.history.push('/service-center/lists')}
          >
            Back
          </Button>

          <PermissionChecker permissionSetter='ops.create_service_center' permissionGetter={permissions}>
            <RightSideButton>
              <Button type='primary' onClick={() => setUpdateModalOpen(true)}>
                Update Service Center Detail
              </Button>

              {false &&
                <Upload>
                  <Button type='primary' icon='plus'>
                    Upload Branch
                  </Button>
                </Upload>}

            </RightSideButton>
          </PermissionChecker>
        </ButtonWrapper>

        <Card style={{ marginTop: 24 }}>
          <Spin spinning={getServiceCenterDetailsLoading} indicator={antIcon}>
            {
              servicecenterDetail.map((detail) => {
                const { title = '', dataIndex = '', render = (text) => text } = detail
                return (
                  <Row key={dataIndex}>
                    <Col span={6}>
                      <div>{title}</div>
                    </Col>
                    <Col>
                      {
                        render
                          ? render(serviceCenterDetailData[dataIndex])
                          : serviceCenterDetailData[dataIndex] || 'N/A'
                      }
                    </Col>
                  </Row>
                )
              })
            }
          </Spin>
        </Card>

        <BankButtonWrapper>
          <BulkUploadBranchDetails
            serviceCenterCode={id}
          />
        </BankButtonWrapper>

        <Card>
          <BranchList serviceCenterCode={id} />
        </Card>

        <Card>
          <ServiceCenterUser permissions={permissions} />
        </Card>
        <Card>
          <ServicecenterConfig />
        </Card>
      </LayoutContent>
    </ErrorBoundary>
  )
}

export default connect((state) => ({
  serviceCenterDetailData: state.ServiceCenter.getServiceCenterDetail,
  getServiceCenterDetailMessage: state.ServiceCenter.getServiceCenterDetailMessage,

  getServiceCenterDetailsError: state.Error.GET_SERVICE_CENTER_DETAIL,
  getServiceCenterDetailsLoading: state.Loading.GET_SERVICE_CENTER_DETAIL,
  profileData: state.Auth.profile
}), {
  getServiceCenterDetails,
  resetLoadingRedux,
  resetErrorRedux
})(ServiceCenterDetails)
