import { Form, Select, Input, Button } from 'antd'
import _, { get } from 'lodash'
import { useParams } from 'react-router'
import { ErrorText } from '../serviceCenterDetailStyle'

const FormItem = Form.Item
const Option = Select.Option

function AddEditServiceCenterConfig ({
  form,
  handleCancel,
  existingServiceCenterConfig,
  defaultConfigList,
  submitServiceCenterConfig,
  addEditServiceCenterConfigLoading
}) {
  const params = useParams()

  const isEdit = !!(Array.isArray(existingServiceCenterConfig) && existingServiceCenterConfig.length)

  const configData = Array.isArray(existingServiceCenterConfig) && existingServiceCenterConfig.length
    ? existingServiceCenterConfig
    : (
        Array.isArray(defaultConfigList)
          ? defaultConfigList.map((config) => ({
              config_type: {
                ...config
              },
              value: _.get(config, 'default_value', undefined)
            }))
          : []
      )

  const renderInputField = (fieldType) => {
    switch (fieldType) {
      case 'bool':
        return (
          <Select>
            <Option value='1'>Yes</Option>
            <Option value='0'>No</Option>
          </Select>
        )
      default:
        return <Input />
    }
  }

  const { getFieldDecorator } = form

  const onSubmit = (e) => {
    e.preventDefault()

    form.validateFields((err, values) => {
      if (err) return
      const payload = {
        serviceuser_code: _.get(params, 'id', ''),
        servicecenter_configs: Object.keys(values).map((key) => ({
          config_type_name: key,
          value: values[key]
        })),
        isEdit
      }
      submitServiceCenterConfig(payload)
    })
  }
  return (
    <Form
      onSubmit={onSubmit}
    >
      {
        Array.isArray(configData) && configData.length > 0
          ? configData.map(({ config_type: configType, value }) =>
              (
                <FormItem key={JSON.stringify(configType)} label={get(configType, 'description')}>
                  {getFieldDecorator(get(configType, 'name'), {
                    rules: [
                      { required: true, message: `${get(configType, 'name')} can not be empty` }
                    ],
                    initialValue: value ?? undefined
                  })(
                    renderInputField(get(configType, 'field_type'))
                  )}
                </FormItem>
              ))
          : (
            <ErrorText>
              There is not existing config and defalut config is also not available right now. You can try later.
            </ErrorText>
            )
      }
      <Button key='back' onClick={handleCancel}>Cancel</Button>
      <Button
        disabled={!(configData.length)}
        key='submit'
        type='primary'
        htmlType='submit'
        style={{ marginLeft: '10px' }}
        loading={addEditServiceCenterConfigLoading}
      >
        Submit
      </Button>
    </Form>

  )
}

export default Form.create()(AddEditServiceCenterConfig)
