import { useState } from 'react'
import { Button, Col, Divider, Modal, Row } from 'antd'
import { get } from 'lodash'
import { useParams } from 'react-router-dom'
import ServiceCenterUserList from './servicecenterUserList'
import { Container } from './serviceCenterDetailStyle'
import AddServicecenterUser from './addServicecenterUser'
import PermissionCheckerV2 from '../../../components/permissionCheckerV2'

function ServiceCenterUser (props) {
  const [showAddUserModal, setShowAddUserModal] = useState(false)
  const params = useParams()

  const servicecenterCode = get(params, 'id', '')

  const { permissions } = props

  return (
    <Container>
      <>
        <Modal
          visible={showAddUserModal}
          title='Service Center User'
          footer={null}
          onCancel={() => setShowAddUserModal(false)}
        >
          <AddServicecenterUser
            visible={showAddUserModal}
            serviceCenterCode={servicecenterCode}
            closeModal={() => setShowAddUserModal(false)}
            editUserData={{}}
          />
        </Modal>
        <Row type='flex' justify='space-between'>
          <Col className='header'>Service Center User</Col>
          <PermissionCheckerV2
            permissions={permissions}
            requiredPermission='ops.update_service_center'
          >
            <Col>
              <Button
                onClick={() => setShowAddUserModal(true)}
                type='primary'
              >
                Add new Service center User
              </Button>
            </Col>
          </PermissionCheckerV2>
        </Row>
        <Divider />
        <ServiceCenterUserList />
      </>
    </Container>
  )
}

export default ServiceCenterUser
