import { Table, Row, Col, Icon, notification, Modal } from 'antd'
import { get } from 'lodash'
import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { useParams } from 'react-router-dom'

import ServiceCenterActions from '../../redux/serviceCenter/actions'
import ErrorAction from '../../../redux/error/actions'
import LoadingActions from '../../../redux/loading/actions'
import { ServiceCenterUserListContainer, ErrorText } from './serviceCenterDetailStyle'
import AddServiceCenterUser from './addServicecenterUser'
import PermissionCheckerV2 from '../../../components/permissionCheckerV2'

const {
  resetServiceCenterRedux,
  getServiceCenterGroupList,
  getServiceCenterUsersList,
  changeServicecenterUserStatus
} = ServiceCenterActions

const { resetErrorRedux } = ErrorAction
const { resetLoadingRedux } = LoadingActions

function ServiceCenterUserList ({
  resetServiceCenterRedux,
  getServiceCenterGroupList,
  serviceCenterUsersList,
  getServiceCenterListError,
  getServiceCenterUsersList,
  getServiceCenterListLoading,
  changeServicecenterUserStatus,
  changeServicecenterUserStatusLoading,
  changeServicecenterUserStatusMessage,
  changeServicecenterUserStatusError
}) {
  const params = useParams()

  const servicecenterCode = get(params, 'id', '')

  const [state, setState] = useState({})

  useEffect(() => {
    getServiceCenterUsersList({
      code: servicecenterCode
    })
    getServiceCenterGroupList({})
  }, [
    getServiceCenterUsersList,
    getServiceCenterGroupList,
    servicecenterCode
  ])

  useEffect(() => {
    if (changeServicecenterUserStatusLoading === false) {
      changeServicecenterUserStatusMessage && notification[changeServicecenterUserStatusError ? 'error' : 'success']({
        message: changeServicecenterUserStatusMessage
      })
      resetErrorRedux(['CHANGE_SERVICE_CENTER_USER_STATUS'])
      resetLoadingRedux(['CHANGE_SERVICE_CENTER_USER_STATUS'])
      resetServiceCenterRedux(['changeServicecenterUserStatusMessage'])
    }
  }, [
    resetServiceCenterRedux,
    changeServicecenterUserStatusLoading,
    changeServicecenterUserStatusError,
    changeServicecenterUserStatusMessage
  ])

  const handleStatusChange = (value) => {
    const { id, is_active: isActive } = value
    changeServicecenterUserStatus({
      activate: !isActive,
      user_id: id,
      code: servicecenterCode
    })
  }

  const columns = [
    {
      title: 'Name',
      dataIndex: 'name'
    },
    {
      title: 'Email address',
      dataIndex: 'email'
    },
    {
      title: 'Is internal user',
      dataIndex: 'is_internal_user',
      render: (data) => data ? 'True' : 'False'
    },
    {
      title: 'Status',
      dataIndex: 'is_active',
      render: (data) => data ? 'True' : 'False'
    },
    {
      title: 'Actions',
      key: 'action',
      align: 'center',
      render: value => (
        <PermissionCheckerV2 requiredPermission='ops.update_service_center'>
          <Row type='flex' justify='space-between'>
            <Col>
              <div className='revoke-button' onClick={() => handleStatusChange(value)}>
                {get(value, 'is_active') ? 'Revoke' : 'Activate'}
              </div>
            </Col>
            {get(value, 'is_active') &&
              <Col>
                <Icon
                  type='edit'
                  onClick={() => setState({ showAddUserModal: true, editUserData: value })}
                />
              </Col>}
          </Row>
        </PermissionCheckerV2>
      )
    }
  ]
  const { showAddUserModal, editUserData } = state
  return (
    <ServiceCenterUserListContainer>
      <Modal
        visible={showAddUserModal}
        title='Service Center User'
        footer={null}
        onCancel={() => setState({ showAddUserModal: false, editUserData: {} })}
      >
        <AddServiceCenterUser
          visible={showAddUserModal}
          serviceCenterCode={servicecenterCode}
          closeModal={() => setState({ showAddUserModal: false, editUserData: {} })}
          editUserData={editUserData}
        />
      </Modal>
      <Table
        columns={columns}
        loading={getServiceCenterListLoading}
        dataSource={Array.isArray(serviceCenterUsersList) ? serviceCenterUsersList : []}
      />
      {
        getServiceCenterListError &&
        (
          <ErrorText>
            Service center listing is not working. Kindly try after some time.
          </ErrorText>
        )
      }
    </ServiceCenterUserListContainer>
  )
}

export default connect((state) => ({
  changeServicecenterUserStatusError: state.Error.CHANGE_SERVICE_CENTER_USER_STATUS,
  changeServicecenterUserStatusMessage: state.ServiceCenter.changeServicecenterUserStatusMessage,
  getServiceCenterListLoading: state.Loading.GET_SERVICE_CENTER_USER_LIST,
  getServiceCenterListError: state.Error.GET_SERVICE_CENTER_USER_LIST,
  changeServicecenterUserStatusLoading: state.Loading.CHANGE_SERVICE_CENTER_USER_STATUS,
  serviceCenterUsersList: state.ServiceCenter.serviceCenterUsersList
}), {
  resetServiceCenterRedux,
  getServiceCenterGroupList,
  getServiceCenterUsersList,
  resetErrorRedux,
  resetLoadingRedux,
  changeServicecenterUserStatus
})(ServiceCenterUserList)
