import { useEffect, useState, useMemo } from 'react'
import { connect } from 'react-redux'
import { Link, useHistory, useLocation } from 'react-router-dom'
import moment from 'moment'
import _ from 'lodash'
import { Table, Input, Button, Icon, Tag, notification, Modal } from 'antd'
import Highlighter from 'react-highlight-words'

import ServiceCenterActions from '../../redux/serviceCenter/actions'
import ErrorAction from '../../../redux/error/actions'
import LoadingActions from '../../../redux/loading/actions'

import QuerySearchBuilder from '../../../helpers/querySearchBuilder'

import {
  FlexGapContainer,
  BranchListWrapper,
  TotalBranchContainer,
  FilterTagContainers
} from './serviceCenterDetailStyle'

import { branchColumns } from './branchListColumns'
import PermissionCheckerV2 from '../../../components/permissionCheckerV2'
import FilterBrand from './filterBrand'

const DISABLE_SERVICE_CENTER_BRAND_FLOW = process.env.REACT_APP_DISABLE_SERVICE_CENTER_BRAND_FLOW === 'true'

const { confirm } = Modal

const {
  getServiceCenterBrandList,
  resetServiceCenterRedux,
  getServiceCenterBranchList,
  inactiveBulkServiceCenterBranch,
  downloadCurrentBranchData
} = ServiceCenterActions

const { resetErrorRedux } = ErrorAction
const { resetLoadingRedux } = LoadingActions

function useQuery () {
  const { search } = useLocation()

  return useMemo(() => new URLSearchParams(search), [search])
}

function ServiceCenterBranchList (props) {
  const {
    brandList,
    profileData,
    resetErrorRedux,
    resetLoadingRedux,
    serviceCenterCode,
    serviceCenterBranchList,
    getServiceCenterBrandList,
    resetServiceCenterRedux,
    serviceCenterListLoading,
    downloadCurrentBranchData,
    getServiceCenterBranchList,
    inactiveServiceCenterMessage,
    downloadCurrentBranchDataError,
    downloadCurrentBranchDataLoading,
    downloadCurrentBranchDataMessage,
    inactiveBulkServiceCenterBranchError,
    inactiveBulkServiceCenterBranchLoading,
    inactiveBulkServiceCenterBranch = () => { }
  } = props
  const query = useQuery()
  const location = useLocation()

  const permissions = _.get(profileData, 'permissions', [])

  const getInitialState = () => {
    const obj = {}
    for (const [key, value] of query) {
      obj[key] = value
    }
    delete obj.page_size
    delete obj.page
    return obj
  }

  const [searchObject, setSearchData] = useState(getInitialState())
  const [selectedBranchCode, setSelectedBranchCode] = useState([])

  const history = useHistory()

  useEffect(() => {
    if (!DISABLE_SERVICE_CENTER_BRAND_FLOW) {
      getServiceCenterBrandList()
    }
  }, [getServiceCenterBrandList])

  useEffect(() => {
    if (inactiveBulkServiceCenterBranchLoading === false) {
      notification[inactiveBulkServiceCenterBranchError ? 'error' : 'success']({
        message: inactiveServiceCenterMessage || ''
      })
      if (inactiveBulkServiceCenterBranchError === false) {
        setSelectedBranchCode([])
      }
      resetLoadingRedux(['INACTIVE_SERVICE_CENTER_BRANCH'])
      resetErrorRedux(['INACTIVE_SERVICE_CENTER_BRANCH'])
      resetServiceCenterRedux(['inactiveServiceCenterMessage'])
    }
  }, [
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    inactiveServiceCenterMessage,
    inactiveBulkServiceCenterBranchError,
    inactiveBulkServiceCenterBranchLoading
  ])

  useEffect(() => {
    if (downloadCurrentBranchDataLoading === false) {
      notification[downloadCurrentBranchDataError ? 'error' : 'success']({
        message: downloadCurrentBranchDataMessage || ''
      })
      resetLoadingRedux(['DOWNLOAD_CURRENT_BRANCH_DETAIL'])
      resetErrorRedux(['DOWNLOAD_CURRENT_BRANCH_DETAIL'])
      resetServiceCenterRedux(['downloadCurrentBranchDataMessage'])
    }
  }, [
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    downloadCurrentBranchDataMessage,
    downloadCurrentBranchDataError,
    downloadCurrentBranchDataLoading
  ])

  useEffect(() => {
    const queryParams = {}

    for (const [key, value] of query) {
      queryParams[key] = value
    }

    getServiceCenterBranchList({
      service_center_code: [serviceCenterCode],
      page_size: 10,
      page: query.has('page') ? query.get('page') : 1,
      ...queryParams
    })

    delete queryParams.page

    setSearchData({
      ...queryParams
    })
  }, [
    query,
    history,
    location.pathname,
    serviceCenterCode,
    getServiceCenterBranchList
  ])

  useEffect(() => {
    const page = query.has('page') ? query.get('page') : 1
    const searchQuery = QuerySearchBuilder({ ...searchObject, page })
    if (searchQuery !== location.search) {
      history.push({ pathname: location.pathname, search: searchQuery })
    }
  }, [
    searchObject
  ])

  let searchInput

  const handleSearch = (selectedKeys, confirm, dataIndex) => {
    confirm()
    const searchQuery = QuerySearchBuilder({ ...searchObject, [dataIndex]: selectedKeys })
    history.push({ pathname: location.pathname, search: searchQuery })

    setSearchData({
      ...searchObject,
      [dataIndex]: selectedKeys
    })
  }

  const handleReset = clearFilters => {
    clearFilters()
    setSearchData({})
  }

  const shouldAllowToOpenLink = useMemo(() => {
    return Array.isArray(permissions) ? permissions.includes('ops.update_service_center') : false
  }, [permissions])

  const handleBrandSearch = (selected, confirm) => {
    confirm()
    setSearchData({
      ...searchObject,
      brand: selected ? selected.join(',') : undefined
    })
  }

  const getColumnSearchPropsBrandFilter = (dataIndex) => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <FilterBrand
        ref={node => {
          searchInput = node
        }}
        selectedBrand={searchObject.brand}
        brandList={brandList}
        onChange={(selected) => handleBrandSearch(selected, confirm)}
      />
    ),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => searchInput)
      }
    },
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    render: (brandList) => {
      if (!Array.isArray(brandList)) return ''
      return brandList.map(({ brand_name: name }) => name).join(', ')
    }
  })

  const getColumnSearchProps = (dataIndex) => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button onClick={() => handleReset(clearFilters)} size='small' style={{ width: 90 }}>
          Reset
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => searchInput.select())
      }
    },
    render: text => {
      let data = text
      if (dataIndex === 'is_pickup_service_available') {
        data = data ? 'Yes' : 'No'
      }

      if (dataIndex === 'is_active') {
        data = data ? 'Active' : 'Inactive'
      }

      if (dataIndex === 'branch_code') {
        return shouldAllowToOpenLink
          ? <Link to={`/service-center/${serviceCenterCode}/branch/${data}`}>{data}</Link>
          : data
      }

      return searchObject[dataIndex]
        ? <Highlighter
            highlightStyle={{ backgroundColor: '#ffc069', padding: 0 }}
            searchWords={[searchObject[dataIndex]]}
            textToHighlight={data ? data.toString() : ''}
          />
        : (
            data || ''
          )
    }
  })

  const pageChangeHandler = (page) => {
    const searchQuery = QuerySearchBuilder({ ...searchObject, page })
    history.push({ pathname: location.pathname, search: searchQuery })
  }

  const renderFilterTags = () => {
    const res = []
    for (const filter in searchObject) {
      res.push({
        key: filter,
        value: searchObject[filter]
      })
    }
    return res
  }

  const closeFilter = (key) => {
    const newSearchObject = { ...searchObject }
    delete newSearchObject[key]
    setSearchData(newSearchObject)
    const searchQuery = QuerySearchBuilder({ ...newSearchObject, page: 1 })
    history.push({ pathname: location.pathname, search: searchQuery })
  }

  const rowSelection = {
    selectedRowKeys: selectedBranchCode,
    onChange: (selectedRowKeys, selectedRows = []) => {
      setSelectedBranchCode(selectedRowKeys)
    },
    getCheckboxProps: record => ({
      disabled: !record.is_active
    })
  }

  const inactiveBranchClickHandler = () => {
    if (!selectedBranchCode.length) return

    confirm({
      title: 'Deactive Branch',
      content: `This will deactivate the ${selectedBranchCode.length} branches`,
      okText: 'Confirm',
      onOk: () => {
        inactiveBulkServiceCenterBranch({
          selectedBranchCode,
          serviceCenterCode
        })
      },
      onCancel: () => { }
    })
  }

  const downloadCurrentBranchDataClickHandler = (event) => {
    event.preventDefault()
    downloadCurrentBranchData({ service_center_code: serviceCenterCode })
  }

  const branchData = _.get(serviceCenterBranchList, 'data', []).map((branch) => ({
    ...branch,
    key: branch.branch_code
  }))

  return (
    <BranchListWrapper>
      <TotalBranchContainer>
        <div>
          Number of registered service branch:
          <span>
            {_.get(serviceCenterBranchList, 'meta_data.total_records', 0)}
          </span>
        </div>

        <FlexGapContainer>
          <Button
            type='primary'
            onClick={downloadCurrentBranchDataClickHandler}
            loading={downloadCurrentBranchDataLoading}
          >
            Download Branch data
          </Button>
          <PermissionCheckerV2
            requiredPermission='ops.update_service_center'
          >
            <Button
              type='primary'
              onClick={inactiveBranchClickHandler}
              disabled={!selectedBranchCode.length}
              loading={inactiveBulkServiceCenterBranchLoading}
            >
              Deactivate selected branch
            </Button>
          </PermissionCheckerV2>
        </FlexGapContainer>

      </TotalBranchContainer>
      <FilterTagContainers>
        {renderFilterTags().map(({ key, value }) => (
          <Tag closable onClose={() => closeFilter(key)} key={key}>
            {key} - {value}
          </Tag>
        ))}
      </FilterTagContainers>
      <Table
        rowClassName={(record) => {
          const { is_active: isActive } = record
          return !isActive ? 'table-row-inactive' : ''
        }}
        rowSelection={rowSelection}
        columns={branchColumns({ moment, getColumnSearchProps, getColumnSearchPropsBrandFilter, DISABLE_SERVICE_CENTER_BRAND_FLOW })}
        bordered
        pagination={{
          pageSize: 10,
          total: _.get(serviceCenterBranchList, 'meta_data.total_records', 0),
          onChange: pageChangeHandler,
          current: query.has('page') ? query.get('page') : 1
        }}
        dataSource={branchData}
        loading={serviceCenterListLoading}
        className='isoSearchableTable'
        scroll={{ x: true }}
      />
    </BranchListWrapper>
  )
}

export default connect((state) => ({
  profileData: state.Auth.profile,
  serviceCenterBranchList: state.ServiceCenter.serviceCenterBranchList,
  inactiveServiceCenterMessage: state.ServiceCenter.inactiveServiceCenterMessage,
  brandList: state.ServiceCenter.brandList,

  downloadCurrentBranchDataMessage: state.ServiceCenter.downloadCurrentBranchDataMessage,

  serviceCenterListLoading: state.Loading.GET_SERVICE_CENTER_BRANCH_LIST_DETAIL,
  inactiveBulkServiceCenterBranchLoading: state.Loading.INACTIVE_SERVICE_CENTER_BRANCH,
  downloadCurrentBranchDataLoading: state.Loading.DOWNLOAD_CURRENT_BRANCH_DETAIL,

  inactiveBulkServiceCenterBranchError: state.Error.INACTIVE_SERVICE_CENTER_BRANCH,
  downloadCurrentBranchDataError: state.Error.DOWNLOAD_CURRENT_BRANCH_DETAIL
}), {
  getServiceCenterBrandList,
  resetLoadingRedux,
  resetErrorRedux,
  resetServiceCenterRedux,
  downloadCurrentBranchData,
  getServiceCenterBranchList,
  inactiveBulkServiceCenterBranch
})(ServiceCenterBranchList)
